package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.AuthDtos.*; import br.com.tapeteskalke.security.CurrentUser; import br.com.tapeteskalke.service.AuthService; import br.com.tapeteskalke.service.UsuarioService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final AuthService auth; private final CurrentUser current; private final UsuarioService usuarios; public AuthController(AuthService auth,CurrentUser current,UsuarioService usuarios){this.auth=auth;this.current=current;this.usuarios=usuarios;} @PostMapping("/login") public ResponseEntity<ApiResponse<LoginResponse>> login(@Valid @RequestBody LoginRequest r,jakarta.servlet.http.HttpServletRequest request){return ResponseEntity.ok(ApiResponse.ok(auth.login(r,request.getRemoteAddr())));} @GetMapping("/me") public ApiResponse<UserResponse> me(){return ApiResponse.ok(auth.me(current.require()));} @PostMapping("/logout") public ResponseEntity<Void> logout(){auth.logout(current.require());return ResponseEntity.noContent().build();} @PutMapping("/senha") public ResponseEntity<Void> trocarSenha(@Valid @RequestBody UsuarioDtos.TrocarSenhaRequest r){usuarios.trocarPropriaSenha(r);return ResponseEntity.noContent().build();} }